    "content": "'''\n# # WAP to find square root\nnum = int(input(\"Enter a number : \"))\nsquare = num**0.5\nprint(\"The Square root of \", num ,\" is \", square);\n\n# # WAP to calculate Simple Interest\np = int(input(\"Enter principle amount : \"))\nr = float(input(\"Enter rate of interest : \"))\nn = float(input(\"Enter number of years : \"))\nSI = (p*r*n)/100\nprint(\"Simple Interest = \",SI)\n\n# # area , permimeter of circle \nfrom math import pi as PI\nradius = 10\narea = PI * radius**2  # pi r square \nperimetre = 2 * PI * radius # 2 pi  r \nprint(\"Area of Circle = \", area)\nprint(\"Perimeter of circle = \", perimetre)\n\n# # celcius -> ferhenite\nf = 95.5\nc = ( f - 32)/ 1.8 \n# ferhenite ->  celcius\nf =  (c* 1.8 ) + 32\nprint(\"f = \", f)\nprint(\"C = \", c)\n\n\n#---- for chapter 4\ndef intro():\n    print(\"This is chapter 1 file...\")\n\ndef generateFibbo(n):\n    a , b = 0,1\n    while b < n:\n        print( b, end=\" \")\n        a,b = b , a+b\n    print()\n\n\n# a = 100\n# print(id(a))\n# b = a \n# print(id(b))\n# b +=1\n# print(id(b))\n\n\n# T = ('spam', 'Spam', 'SPAM!', 'SaPm') \n# print (T [2]) \n# print (T[-2])  \n# print (T[2:])  \n# print (list(T)) \n\n# T = ('spam,Spam', 'SPAM!', 'SaPm') \n# print (T [2]) \n# print (T[-2])  \n# print (T[2:])  \n# print (list(T)) \n'''"
