    "content": "import math\nfrom turtle import *\n\ndef hearta(self):\n    return 15*math.sin(self)**3\n\ndef heartb(self):\n    return 12*math.cos(self)-5*\\\n        math.cos(2*self)-2*\\\n        math.cos(3*self)-\\\n        math.cos(4*self)\nspeed(0)\nbgcolor(\"black\")\nfor i in range(6000):\n    goto(hearta(i)*20,heartb(i)*20)\n    for j in range(5):\n        color(\"#f73487\")\n    goto(0,0)\ndone()"
