    "content": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Expandable Table Row with Plus Sign Button</title>\n  <style>\n    table {\n      width: 100%;\n      border-collapse: collapse;\n    }\n    th, td {\n      padding: 10px;\n      border: 1px solid #ccc;\n    }\n    .expandable-content {\n      display: none;\n      background-color: #f9f9f9;\n      padding: 10px;\n    }\n    .dropdown-btn {\n      cursor: pointer;\n      background-color: #4CAF50;\n      color: white;\n      border: none;\n      padding: 5px;\n      font-size: 20px; /* Larger font for the plus sign */\n      text-align: center;\n    }\n    .dropdown-btn:focus {\n      outline: none;\n    }\n  </style>\n</head>\n<body>\n\n<table>\n  <thead>\n    <tr>\n      <th>Name</th>\n      <th>Age</th>\n      <th>Details</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>John Doe</td>\n      <td>28</td>\n      <td><button class=\"dropdown-btn\" onclick=\"toggleContent(this)\"> &#9660;</button></td>\n    </tr>\n    <tr class=\"expandable-content\">\n      <td colspan=\"3\">This is some additional content for John Doe. It can be more detailed information.</td>\n    </tr>\n\n    <tr>\n      <td>Jane Smith</td>\n      <td>32</td>\n      <td><button class=\"dropdown-btn\" onclick=\"toggleContent(this)\"> &#9660;</button></td>\n    </tr>\n    <tr class=\"expandable-content\">\n      <td colspan=\"3\">This is some additional content for Jane Smith.</td>\n    </tr>\n\n    <!-- Row with no content to demonstrate button absence -->\n    <tr>\n      <td>Sam Johnson</td>\n      <td>25</td>\n      <td></td>\n    </tr>\n  </tbody>\n</table>\n\n<script>\n  function toggleContent(button) {\n    const row = button.closest('tr');\n    const nextRow = row.nextElementSibling;\n\n    if (nextRow.classList.contains('expandable-content')) {\n        const isRowVisible = nextRow.style.display === 'table-row';\n      nextRow.style.display = isRowVisible ? 'none' : 'table-row';\n\n      // Update button text to show the appropriate arrow\n      button.innerHTML = isRowVisible ? '&#9660;' : '&#9650;'; // Down arrow (&#9660;) for hidden, Up arrow (&#9650;) for visible\n    }\n  }\n\n  // Hide the expand button if no content exists\n  const rows = document.querySelectorAll('tr');\n  rows.forEach(row => {\n    const button = row.querySelector('.dropdown-btn');\n    if (row.nextElementSibling && row.nextElementSibling.classList.contains('expandable-content') && !row.nextElementSibling.textContent.trim()) {\n      button.style.display = 'none';\n    }\n  });\n</script>\n\n</body>\n</html>\n"
